export function useRatingsReviews() {
  const navigate = useNavigate()
  const goBack = useRestaurantBackNavigation()
  const [expandedItems, setExpandedItems] = useState(new Set())
  const [showThankYouPopup, setShowThankYouPopup] = useState(false)
  const [showNotHelpfulPopup, setShowNotHelpfulPopup] = useState(false)
  const [feedbackSubmitted, setFeedbackSubmitted] = useState(false)

  // Lenis smooth scrolling

  const toggleAccordion = (itemId) => {
    setExpandedItems(prev => {
      const newSet = new Set(prev)
      if (newSet.has(itemId)) {
        newSet.delete(itemId)
      } else {
        newSet.add(itemId)
      }
      return newSet
    })
  }

  const handleThankYou = () => {
    setShowThankYouPopup(true)
    setFeedbackSubmitted(true)
  }

  const handleNotHelpful = () => {
    setShowNotHelpfulPopup(true)
    setFeedbackSubmitted(true)
  }

  const handleThankYouPopupClose = () => {
    setShowThankYouPopup(false)
  }

  const handleNotHelpfulPopupClose = () => {
    setShowNotHelpfulPopup(false)
  }

  return {
    navigate,
    goBack,
    expandedItems,
    setExpandedItems,
    showThankYouPopup,
    setShowThankYouPopup,
    showNotHelpfulPopup,
    setShowNotHelpfulPopup,
    feedbackSubmitted,
    setFeedbackSubmitted,
    toggleAccordion,
    handleThankYou,
    handleNotHelpful,
    handleThankYouPopupClose,
    handleNotHelpfulPopupClose,
    restaurantReviewBanner,
    accordionItems,
  }
}
